// TF_DS_IDX_FUSED, eight scores per candidate and 16-byte-aligned rows (idx_fused.candMask8Ok).
extern "C" __global__ void tf_ds_cand_fast8_kernel(const float* score, long long ss, int nb, int /*bsize*/,
                                                   const long long* vis, uint8_t* out, long long os, int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.y;
    const float4* row = reinterpret_cast<const float4*>(score + (long long)r * ss);
    const long long visible = vis[r];
    const long long last = visible > 0 ? (visible - 1) / 8 : -1;
    const float ninf = -__int_as_float(0x7f800000);
    for (int b = blockIdx.x * blockDim.x + threadIdx.x; b < nb; b += gridDim.x * blockDim.x) {
        const float4 lo = row[2LL * b], hi = row[2LL * b + 1];
        const float values[8] = {lo.x, lo.y, lo.z, lo.w, hi.x, hi.y, hi.z, hi.w};
        bool nan = false, above = false;
        #pragma unroll
        for (int j = 0; j < 8; ++j) {
            nan |= isnan(values[j]);
            above |= values[j] > ninf;
        }
        out[(long long)r * os + b] = (uint8_t)((!nan && above) || b == last);
    }
}

// model.py _candidates / rounds.py _candidate_blocks, their first step: a row's block maxima of the scores (amax over
// blocks of bsize, the last block padded with -inf, a NaN wins), its newest block, (vis - 1) // bsize (floor
// division), pinned to +inf. score [rows, width] fp32 (row stride ss), vis [rows] int64, out [rows, nb] fp32 (row
// stride os), nb = ceil(width / bsize); grid (blocks, rows).
extern "C" __global__ void tf_ds_block_max_kernel(const float* score, long long ss, int width, int bsize,
                                                  const long long* vis, float* out, long long os, int nb, int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.y;
    const long long t = vis[r] - 1;
    const long long last = t >= 0 ? t / bsize : -((-t + bsize - 1) / bsize);
    const float ninf = -__int_as_float(0x7f800000);
    for (int b = blockIdx.x * blockDim.x + threadIdx.x; b < nb; b += gridDim.x * blockDim.x) {
        const float* s = score + (long long)r * ss + (long long)b * bsize;
        float m = ninf;
        bool nan = false;
        for (int j = 0; j < bsize && b * bsize + j < width; ++j) {
            const float x = s[j];
            if (x != x) nan = true;
            else if (x > m) m = x;
        }
        float v = nan ? __int_as_float(0x7fc00000) : m;
        if (b == last) v = __int_as_float(0x7f800000);
        out[(long long)r * os + b] = v;
    }
}

// The pool from a row's top blocks idx [rows, k] (kernels.topk_indices of the block maxima bmax [rows, nb], row stride
// bs): model.py _candidates' mask (u8 [rows, nb], row stride ms: zeros, then each picked block whose maximum is above
// -inf) and/or rounds.py _candidate_blocks' list (int32 [rows, k]: the block, or -1 when its maximum is not above -inf).
// A row a block of threads.
extern "C" __global__ void tf_ds_pool_pick_kernel(const float* bmax, long long bs, int nb, const long long* idx, int k,
                                                  uint8_t* mask, long long ms, int* cblk, int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.x;
    const float ninf = -__int_as_float(0x7f800000);
    if (mask != nullptr) {
        for (int b = threadIdx.x; b < nb; b += blockDim.x) mask[(long long)r * ms + b] = 0;
        __syncthreads();
    }
    for (int j = threadIdx.x; j < k; j += blockDim.x) {
        const long long c = idx[(long long)r * k + j];
        const bool ok = bmax[(long long)r * bs + c] > ninf;
        if (mask != nullptr && ok) mask[(long long)r * ms + c] = 1;
        if (cblk != nullptr) cblk[(long long)r * k + j] = ok ? (int)c : -1;
    }
}

// model.py apply_candidates: -inf at every position whose block the row's pool leaves out (mask u8 [rows, >= ceil(width
// / bsize)], row stride ms), in place. score [rows, width] fp32 (row stride ss); grid (blocks, rows).
extern "C" __global__ void tf_ds_apply_pool_kernel(float* score, long long ss, int width, int bsize, const uint8_t* mask,
                                                   long long ms, int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.y;
    const float ninf = -__int_as_float(0x7f800000);
    for (int j = blockIdx.x * blockDim.x + threadIdx.x; j < width; j += gridDim.x * blockDim.x) {
        if (!mask[(long long)r * ms + j / bsize]) score[(long long)r * ss + j] = ninf;
    }
}

// An inclusive cutoff on the scores for a pool of at most 8192 blocks: the radix scan runs the score's four bytes only
// (digits 7-4). The column bytes are not scanned: when the cutoff bin holds more columns than the slots left, `want_s`
// is that many tied columns, and the compaction takes the bin's lowest columns in ascending order (the same total order
// as scanning the column digits, without two more full passes over the pool). `want_s` 0 means the bin completed
// exactly, so every column in it is picked.
__device__ __forceinline__ void tf_ds_pool_cut(const float* row, int n, unsigned long long* prefix_s,
                                               unsigned long long* mask_s, int* want_s) {
    __shared__ unsigned int hist[256];
    for (int d = 7; d >= 4; --d) {
        for (int b = threadIdx.x; b < 256; b += blockDim.x) hist[b] = 0;
        __syncthreads();
        const unsigned long long prefix = *prefix_s, mask = *mask_s;
        for (int i = threadIdx.x; i < n; i += blockDim.x) {
            const unsigned long long u = tf_ds_score_key(row[i], i);
            if ((u & mask) == prefix) atomicAdd(&hist[(u >> (8 * d)) & 0xff], 1u);
        }
        __syncthreads();
        // Each lane covers eight descending bins. Only the lane containing the target rank scans its eight counts.
        if (threadIdx.x < 32) {
            const int lane = threadIdx.x;
            const int hi = 255 - 8 * lane;
            const int target = *want_s;
            int count = 0;
            #pragma unroll
            for (int j = 0; j < 8; ++j) count += hist[hi - j];
            int end = count;
            #pragma unroll
            for (int off = 1; off < 32; off <<= 1) {
                const int prev = __shfl_up_sync(0xffffffffu, end, off);
                if (lane >= off) end += prev;
            }
            int rank = target - (end - count);
            if (rank > 0 && rank <= count) {
                int digit = hi;
                while (rank > (int)hist[digit]) {
                    rank -= hist[digit];
                    --digit;
                }
                *want_s = rank == (int)hist[digit] ? 0 : rank;
                *prefix_s = prefix | ((unsigned long long)digit << (8 * d));
                *mask_s = mask | (0xffull << (8 * d));
            }
        }
        __syncthreads();
        if (*want_s == 0) break;
    }
}

// The prefix count of `flag` over this tile's lanes in ascending column order (the block's whole mask reaches the ballot
// and the barrier), and the tile's total.
__device__ __forceinline__ int tf_ds_tile_prefix(bool flag, int* warp_end, int* total, int lane, int warp) {
    const unsigned bits = __ballot_sync(0xffffffffu, flag);
    if (lane == 0) warp_end[warp] = __popc(bits);
    if (threadIdx.x < 32 && threadIdx.x >= ((blockDim.x + 31) >> 5)) warp_end[threadIdx.x] = 0;  // (a block below 1024)
    __syncthreads();
    if (warp == 0) {
        int t = warp_end[lane];
        #pragma unroll
        for (int step = 1; step < 32; step <<= 1) {
            const int prev = __shfl_up_sync(0xffffffffu, t, step);
            if (lane >= step) t += prev;
        }
        warp_end[lane] = t;
    }
    __syncthreads();
    *total = warp_end[31];
    return (warp ? warp_end[warp - 1] : 0) + __popc(bits & ((1u << lane) - 1));
}

// One CTA owns a candidate row. Keep the maxima on chip for radix selection.
// Compact selected columns in input order so neither the mask nor the list needs a sort. The maxima and the selection
// live only on chip: the call sites read the mask (the prompt arm) or the block list (decode), never bmax/pidx, so the
// fused launch writes neither (the unfused blockMax/topkIndices/poolPick sequence still does).
// The block maxima (tf_ds_block_max_kernel's rule) for every block this thread owns, on chip. BS == 8 is the served
// block size, instantiated with the trip count static: two aligned 16-byte loads a block, then the same comparison order
// as the scalar loop (a NaN wins; otherwise a greater score replaces the maximum), and a guarded scalar tail for the
// row's last partial block. BS == 0 keeps the runtime size (every other `bsize` and every unfused-shape fallback).
template <int BS>
__device__ __forceinline__ void tf_ds_block_max_t(float* maxima, const float* row, int width, int nb, long long last,
                                                  int bsize = 0) {
    const float ninf = -__int_as_float(0x7f800000);
    const int bs = BS ? BS : bsize;
    for (int b = threadIdx.x; b < nb; b += blockDim.x) {
        const float* s = row + (long long)b * bs;
        float m = ninf;
        bool nan = false;
        if (BS == 8 && b * 8 + 8 <= width) {
            const float4 lo = *reinterpret_cast<const float4*>(s);
            const float4 hi = *reinterpret_cast<const float4*>(s + 4);
            const float x[8] = {lo.x, lo.y, lo.z, lo.w, hi.x, hi.y, hi.z, hi.w};
            #pragma unroll
            for (int j = 0; j < 8; ++j) {
                if (x[j] != x[j]) nan = true;
                else if (x[j] > m) m = x[j];
            }
        } else {
            for (int j = 0; j < bs && b * bs + j < width; ++j) {
                const float x = s[j];
                if (x != x) nan = true;
                else if (x > m) m = x;
            }
        }
        float v = nan ? __int_as_float(0x7fc00000) : m;
        if (b == last) v = __int_as_float(0x7f800000);
        maxima[b] = v;
    }
}

// The pool's selection and its two outputs: the cutoff on the score digits with the tied columns resolved during
// compaction (tf_ds_pool_cut), then either the mask alone (the prompt arm: no ballot, prefix sum or compaction) or the
// decode arm's ascending block list. `maxima` is on chip, one block a column, `limit` the row's `every`.
__device__ __forceinline__ void tf_ds_idx_select(float* maxima, int nb, int k, uint8_t* mask, long long ms, int* cblk,
                                                 int r, long long limit) {
    __shared__ unsigned long long prefix_s, mask_s;
    __shared__ int want_s;
    __shared__ int warp_end[32];
    if (threadIdx.x == 0) {
        // k == nb picks every block: mask 0 makes every key "tied", and want 0 picks the whole bin
        const bool all = k == nb;
        prefix_s = all ? 0ull : 0xffff0000ull;   // (inverted columns below 8192 have two constant high bytes)
        mask_s = all ? 0ull : 0xffff0000ull;
        want_s = all ? 0 : k;
    }
    __syncthreads();
    if (k != nb) tf_ds_pool_cut(maxima, nb, &prefix_s, &mask_s, &want_s);
    __syncthreads();
    const unsigned long long prefix = prefix_s, cmask = mask_s;
    const int want = want_s;
    const float ninf = -__int_as_float(0x7f800000);
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (cblk == nullptr) {
        // the prompt arm reads only the mask: each block's bit straight from the cutoff, no ballot, prefix sum or
        // compaction unless the cutoff straddles ties (then the tied columns' order needs the prefix)
        int tied_base = 0;
        for (int first = 0; first < nb; first += blockDim.x) {
            const int col = first + threadIdx.x;
            const bool in = col < nb;
            const float value = in ? maxima[col] : ninf;
            const unsigned long long u = tf_ds_score_key(value, col);
            bool picked;
            if (want == 0) picked = in && (u >= prefix);   // (the whole cutoff bin, no tie split)
            else {
                const bool above = in && ((u & cmask) > prefix);
                const bool tied = in && ((u & cmask) == prefix);
                int before, total;
                before = tf_ds_tile_prefix(tied, warp_end, &total, lane, warp);
                picked = above || (tied && (tied_base + before) < want);
                tied_base += total;
                __syncthreads();   // the tile's total is read before warp_end is reused
            }
            if (mask != nullptr && in) mask[(long long)r * ms + col] = (uint8_t)(picked && col < limit && value > ninf);
        }
    } else {
        // decode: compact the selected blocks in ascending column order (the tied cutoff's slots go to its lowest
        // columns, which is the ascending scan's first `want` of them)
        int base = 0, tied_base = 0, ttotal = 0;
        for (int first = 0; first < nb; first += blockDim.x) {
            const int col = first + threadIdx.x;
            const bool in = col < nb;
            const float value = in ? maxima[col] : ninf;
            const unsigned long long u = tf_ds_score_key(value, col);
            bool picked;
            if (want == 0) picked = in && (u >= prefix);   // (the whole cutoff bin, no tie split)
            else {
                const bool above = in && ((u & cmask) > prefix);
                const bool tied = in && ((u & cmask) == prefix);
                const int tbefore = tf_ds_tile_prefix(tied, warp_end, &ttotal, lane, warp);
                picked = above || (tied && (tied_base + tbefore) < want);
                tied_base += ttotal;
                __syncthreads();   // the tied total is read before warp_end is reused
            }
            int before, total;
            before = tf_ds_tile_prefix(picked, warp_end, &total, lane, warp);
            const bool valid = picked && col < limit && value > ninf;
            if (mask != nullptr && in) mask[(long long)r * ms + col] = (uint8_t)valid;
            if (picked) cblk[(long long)r * k + base + before] = valid ? col : -1;
            base += total;
            __syncthreads();   // all warps consumed the offsets before the next tile
        }
    }
}

extern "C" __global__ void __launch_bounds__(1024) tf_ds_idx_fused_kernel(const float* score, long long ss, int width,
                                                                          int bsize, const long long* vis,
                                                                          const long long* every, int k,
                                                                          uint8_t* mask, long long ms, int* cblk,
                                                                          int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.x;
    const int nb = 1 + (width - 1) / bsize;
    extern __shared__ float maxima[];
    const float* row = score + (long long)r * ss;
    // phase 1: the block maxima; the served block size with a 16-byte-aligned row stride takes the static, vectorized
    // form, anything else the runtime loop (the same arithmetic, so both are byte-identical)
    const long long visible = vis[r];
    const long long last = visible > 0 ? (visible - 1) / bsize : -1;
    if (bsize == 8 && (ss & 3) == 0) tf_ds_block_max_t<8>(maxima, row, width, nb, last);
    else tf_ds_block_max_t<0>(maxima, row, width, nb, last, bsize);
    __syncthreads();
    tf_ds_idx_select(maxima, nb, k, mask, ms, cblk, r, every[r]);
}

// The same selection from the block maxima in global memory (block_max's output): the small-row form's second launch,
// one CTA a row. The maxima are staged on chip once, so the radix passes and the compaction stay shared-memory work.
extern "C" __global__ void __launch_bounds__(1024) tf_ds_idx_pick_kernel(const float* bmax, long long bs, int nbk, int k,
                                                                        const long long* every, int* cblk, int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.x;
    extern __shared__ float maxima[];
    const float* src = bmax + (long long)r * bs;
    for (int b = threadIdx.x; b < nbk; b += blockDim.x) maxima[b] = src[b];
    __syncthreads();
    tf_ds_idx_select(maxima, nbk, k, nullptr, 0, cblk, r, every[r]);
}

// Rows of n16 16-byte words: dst row r = src row r (row strides in words). torch_ops' tf_strided_copy takes a block a
// row and a byte a thread; this one a word a thread over grid (ceil(n16 / blockDim), rows). Every pointer, stride and
// row length a multiple of 16 bytes (ops.copyRows checks).
extern "C" __global__ void tf_ds_copy_rows16_kernel(const uint4* src, unsigned long long src_ld, uint4* dst,
                                                    unsigned long long dst_ld, unsigned long long n16, int pdl) {
    pdl_enter(pdl);
    const unsigned long long r = blockIdx.y;
    const unsigned long long i = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n16) dst[r * dst_ld + i] = src[r * src_ld + i];
}

// A greedy row's token as sampling.argmax takes it on the host (best = 0; best = i where row[i] > row[best]): the
// first index of the largest value, a NaN never larger, and 0 when the row's first value is NaN. Every thread of a
// 1024-thread block calls it; the token is valid in thread 0.
__device__ unsigned tf_ds_block_argmax_v(const float* row, int n, float* out_v) {
    const float ninf = -__int_as_float(0x7f800000);
    float bv = ninf;
    int bi = 0x7fffffff;
    for (int i = threadIdx.x; i < n; i += blockDim.x) {
        const float v = row[i];
        if (v == v && (v > bv || (v == bv && i < bi))) {
            bv = v;
            bi = i;
        }
    }
    for (int off = 16; off > 0; off >>= 1) {
        const float ov = __shfl_down_sync(0xffffffffu, bv, off);
        const int oi = __shfl_down_sync(0xffffffffu, bi, off);
        if (ov > bv || (ov == bv && oi < bi)) {
            bv = ov;
            bi = oi;
        }
    }
    __shared__ float sv[32];
    __shared__ int si[32];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) {
        sv[warp] = bv;
        si[warp] = bi;
    }
    __syncthreads();
    if (warp != 0) return 0;
    const int nw = (blockDim.x + 31) >> 5;
    bv = lane < nw ? sv[lane] : ninf;
    bi = lane < nw ? si[lane] : 0x7fffffff;
    for (int off = 16; off > 0; off >>= 1) {
        const float ov = __shfl_down_sync(0xffffffffu, bv, off);
        const int oi = __shfl_down_sync(0xffffffffu, bi, off);
        if (ov > bv || (ov == bv && oi < bi)) {
            bv = ov;
            bi = oi;
        }
    }
    *out_v = bv;
    return (unsigned)bi;
}

__device__ unsigned tf_ds_block_argmax(const float* row, int n) {
    float v;
    const unsigned bi = tf_ds_block_argmax_v(row, n, &v);
    return row[0] != row[0] ? 0u : bi;
}

// logits [rows, n] fp32 (row stride ld), out [rows] u32; a row a block (1024 threads).
extern "C" __global__ void __launch_bounds__(1024) tf_ds_argmax_rows_kernel(const float* logits, unsigned long long ld,
                                                                             int n, unsigned* out, int pdl) {
    pdl_enter(pdl);
    const float* row = logits + (unsigned long long)blockIdx.x * ld;
    const unsigned token = tf_ds_block_argmax(row, n);
    if (threadIdx.x == 0) out[blockIdx.x] = token;
}

