    if (rows == 0) return;
    if (score == 0 or vis == 0 or every == 0) return error.BadIdxFusedArgs;
    if (width == 0 or width > std.math.maxInt(c_int) or bsize == 0 or bsize > std.math.maxInt(c_int)) return error.BadIdxFusedArgs;
    const nbk = 1 + (width - 1) / bsize;
    if (ss < width or (mask != 0 and ms < nbk) or nbk > idx_fused.max_nbk or k < 1 or k > idx_fused.max_k or k > nbk) return error.BadIdxFusedArgs;
    var a: cuda.Args = .{};
    a.add(score);
    a.add(@as(c_longlong, @intCast(ss)));
    a.add(@as(c_int, @intCast(width)));
    a.add(@as(c_int, @intCast(bsize)));
    a.add(vis);
    a.add(every);
    a.add(@as(c_int, @intCast(k)));
    a.add(mask);
    a.add(@as(c_longlong, @intCast(ms)));
    a.add(cblk);
    a.add(@as(c_int, @intFromBool(o.pdl)));
    if (fused_trace.enabled()) fused_trace.note(.idx_fused, rows, width, o.pdl);
