/// The 0199 routed-expert prune arm (ops.zig's expertPruneDead).
pub fn pruneArm(fused_route: bool, m: expert_prune.Mode, rows: usize, topk: usize, slots: usize) Arm {
    const ok = fused_route and topk == 6 and slots == 7 and rows > 0 and rows <= 64 and m.cap == null and m.apply and
        m.rule.topp == 0.85 and m.rule.min_k == 3 and m.rule.renorm == .kept;
    return if (ok) .prune_six else .prune_unfused;
}

