// TF_DS_IDX_PICK_WIDE: tf_ds_idx_pick_kernel's selection without the on-chip staging - the row's maxima are read from
// global memory (block_max's output is L2-resident: one fp32 maximum a block, <= 256 KiB a row at 65,536 blocks), so
// the selection reaches past the shared-memory staging bound to 65,536 blocks (the radix shortcut's: the inverted
// column's two constant high bytes; 65,537 keeps the unfused fallback). Same block list as the unfused sequence.
extern "C" __global__ void __launch_bounds__(1024) tf_ds_idx_pick_wide_kernel(const float* bmax, long long bs, int nbk, int k,
                                                                        const long long* every, int* cblk, int pdl) {
    pdl_enter(pdl);
    const int r = blockIdx.x;
    tf_ds_idx_select(bmax + (long long)r * bs, nbk, k, nullptr, 0, cblk, r, every[r]);
}
```

