/// TF_DS_IDX_PICK_WIDE: idxPick's selection for the regime idxPick refuses (idx_fused.max_nbk < nbk <=
/// idx_pick_wide.max_nbk): tf_ds_idx_pick_wide_kernel reads the maxima from global memory instead of staging them
/// on chip (no dynamic shared memory) and writes the same decode block list. The wrapper refuses (rather than falls
/// back) outside its bounds - the call sites only call it after `idx_pick_wide.wideOk` agrees.
pub fn idxPickWide(o: *const Ops, s: cuda.Stream, bmax: u64, bs: usize, width: usize, nbk: usize, k: usize, every: u64, cblk: u64, rows: usize) !void {
    if (rows == 0) return;
    if (bmax == 0 or every == 0 or cblk == 0) return error.BadIdxPickWideArgs;
    if (width == 0 or width > std.math.maxInt(c_int) or nbk <= idx_fused.max_nbk or nbk > idx_pick_wide.max_nbk or nbk > width or bs < nbk or k < 1 or k > idx_fused.max_k or k > nbk) return error.BadIdxPickWideArgs;
    var a: cuda.Args = .{};
    a.add(bmax);
    a.add(@as(c_longlong, @intCast(bs)));
    a.add(@as(c_int, @intCast(nbk)));
    a.add(@as(c_int, @intCast(k)));
    a.add(every);
    a.add(cblk);
    a.add(@as(c_int, @intFromBool(o.pdl)));
    if (fused_trace.enabled()) fused_trace.note(.idx_wide, rows, width, o.pdl);
    try cuda.launch.launch(o.idx_pick_wide_fn orelse return error.IdxPickWideOff, .{ .grid = .{ .x = @intCast(rows) }, .block = .{ .x = 1024 }, .pdl = o.pdl }, s, &a);
}

