edits.newText:
/// The indexer's pool arm: decode (`allow_small = true`, writing `cblk`) takes `idx_small` at `rows <= small_rows` and
/// `nbk >= small_nbk`, `idx_wide` (TF_DS_IDX_PICK_WIDE) at `idx_fused.max_nbk < nbk <= idx_pick_wide.max_nbk`; prompt
/// (`allow_small = false`, writing the `mask`) takes neither because `idxPick`/`idxPickWide` write only decode's
/// block list.
pub fn idxArm(fused: bool, wide: bool, allow_small: bool, rows: usize, width: usize, bsize: usize, nbk: usize, k: usize) Arm {
    if (idx_pick_wide.wideOk(wide, allow_small, rows, width, bsize, nbk, k)) return .idx_wide;
    if (!idx_fused.fuseOk(fused, rows, width, bsize, nbk, k)) return .idx_unfused;
    return if (allow_small and rows <= idx_fused.small_rows and nbk >= idx_fused.small_nbk) .idx_small else .idx_fused;
}

