static uint64_t ref_key(float x, int j) {
    uint32_t bits;
    memcpy(&bits, &x, 4);
    if (bits == 0x80000000u) bits = 0;            // -0 as +0
    int32_t sb;
    memcpy(&sb, &bits, 4);
    int32_t ordered = sb < 0 ? (sb ^ 0x7FFFFFFF) : sb;
    uint64_t key = ((uint64_t)(uint32_t)ordered << 32) | (uint64_t)(0xFFFFFFFFu - (unsigned)j);
    return key ^ 0x8000000000000000ull;
}
