//! h0279's host gate against the WORKTREE's real modules: TF_DS_IDX_PICK_WIDE's arm decisions at BRIEF-0279's case
//! matrix. idx_pick_wide.wideOk + fused_trace.idxArm (imported from the worktree path build.sh passes as -Dwt):
//! 16,385 / 32,768 / 65,536 blocks take the wide arm at rows 1 and 7 with k = 2048 (decode); 65,537 refuses and keeps
//! the unfused three-launch fallback; the switch off, prompt and rows past 7 keep today's arms. Exit 0: all match.
const std = @import("std");
const idx_pick_wide = @import("idx_pick_wide");
const idx_fused = @import("idx_fused");
const fused_trace = @import("fused_trace");

var fails: usize = 0;

fn arm(name: []const u8, wide: bool, allow_small: bool, rows: usize, width: usize, nbk: usize, want: fused_trace.Arm) void {
    const got = fused_trace.idxArm(true, wide, allow_small, rows, width, 8, nbk, 2048);
    const ok = got == want;
    if (!ok) fails += 1;
    std.debug.print("{s}: idxArm(wide={any}, rows={d}, nbk={d}) = {s} (want {s}) {s}\n", .{ name, wide, rows, nbk, @tagName(got), @tagName(want), if (ok) "ok" else "FAIL" });
}

pub fn main() !void {
    std.debug.print("h0279 gate: the worktree's idx_pick_wide.wideOk / fused_trace.idxArm at the brief's matrix\n", .{});
    // the wide window (the served widths: a short last block, width = 8 * nbk - 3, and whole blocks)
    for ([_]usize{ 1, 7 }) |rows| {
        arm("16,385 blocks", true, true, rows, 8 * 16385 - 3, 16385, .idx_wide);
        arm("32,768 blocks", true, true, rows, 8 * 32768, 32768, .idx_wide);
        arm("65,536 blocks", true, true, rows, 8 * 65536, 65536, .idx_wide);
        // 65,537 refuses: the unfused fallback (block_max + topk_indices + pool_pick) stays
        arm("65,537 blocks", true, true, rows, 8 * 65537, 65537, .idx_unfused);
    }
    // the refusal's neighbours and the off path
    arm("switch off", false, true, 7, 8 * 32768, 32768, .idx_unfused);
    arm("prompt arm", true, false, 7, 8 * 32768, 32768, .idx_unfused);
    arm("rows 8", true, true, 8, 8 * 32768, 32768, .idx_unfused);
    // today's regimes unchanged (the off path is byte- and launch-identical)
    arm("staging bound (small)", true, true, 7, 8 * 16384, 16384, .idx_small);
    arm("small pool", true, true, 7, 8 * 6144, 6144, .idx_small);
    arm("many rows (fused)", true, true, 32, 8 * 16384, 16384, .idx_fused);
    arm("prompt pooled", true, false, 1, 65533, 8192, .idx_fused);
    arm("everything off", false, true, 7, 65533, 8192, .idx_unfused);
    // the launcher's own bound: wideOk agrees with the arm table at the 65,536/65,537 edge and the k cap
    if (!idx_pick_wide.wideOk(true, true, 7, 8 * 65536, 8, 65536, idx_fused.max_k)) {
        fails += 1;
        std.debug.print("wideOk(65,536, k=2048): FAIL\n", .{});
    }
    if (idx_pick_wide.wideOk(true, true, 7, 8 * 65537, 8, 65537, idx_fused.max_k)) {
        fails += 1;
        std.debug.print("wideOk(65,537) must refuse: FAIL\n", .{});
    }
    if (idx_pick_wide.wideOk(true, true, 7, 8 * 16385, 8, 16385, idx_fused.max_k + 1)) {
        fails += 1;
        std.debug.print("wideOk(k=2049) must refuse: FAIL\n", .{});
    }
    std.debug.print("h0279 gate: {s} ({d} mismatches)\n", .{ if (fails == 0) "all arms as expected" else "FAIL", fails });
    if (fails != 0) std.process.exit(1);
}

//! h0279's build: gate.zig against the worktree's real idx_pick_wide.zig / idx_fused.zig / fused_trace.zig (and the
//! closure fused_trace pulls). The worktree root comes from -Dwt (build.sh passes it); gate.zig is local. The cuda
//! runtime module is built host-only exactly as zig/build/cuda.zig's runtime() does (no fatbins).
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});
    const wt = b.option([]const u8, "wt", "the worktree root") orelse "";
    const dsv41 = b.pathJoin(&.{ wt, "zig", "src", "families", "dsv41" });

    const options = b.addOptions();
    options.addOption(bool, "with_kernels", false);
    options.addOption(bool, "has_dsv41_port", false);
    const cuda = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ wt, "zig", "src", "cuda", "root.zig" }) }, .target = target, .optimize = optimize, .link_libc = true });
    cuda.addOptions("kernel_options", options);
    cuda.addImport("stagger", b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ wt, "zig", "src", "core", "stagger.zig" }) }, .target = target, .optimize = optimize }));

    const ipw = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ dsv41, "idx_pick_wide.zig" }) }, .target = target, .optimize = optimize, .link_libc = true });
    const idxf = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ dsv41, "idx_fused.zig" }) }, .target = target, .optimize = optimize, .link_libc = true });
    const ft = b.createModule(.{ .root_source_file = .{ .cwd_relative = b.pathJoin(&.{ dsv41, "fused_trace.zig" }) }, .target = target, .optimize = optimize, .link_libc = true });
    ft.addImport("cuda", cuda);

    const gate = b.createModule(.{ .root_source_file = b.path("gate.zig"), .target = target, .optimize = optimize, .link_libc = true, .imports = &.{
        .{ .name = "idx_pick_wide", .module = ipw },
        .{ .name = "idx_fused", .module = idxf },
        .{ .name = "fused_trace", .module = ft },
    } });
    const exe = b.addExecutable(.{ .name = "h0279-gate", .root_module = gate });
    b.installArtifact(exe);
    const run = b.addRunArtifact(exe);
    run.step.dependOn(b.getInstallStep());
    b.step("run", "run the h0279 host gate against the worktree modules").dependOn(&run.step);
}

