const std = @import("std");
const idx_pick_wide = @import("idx_pick_wide");
const idx_fused = @import("idx_fused");
const fused_trace = @import("fused_trace");

var fails: usize = 0;

fn arm(name: []const u8, wide: bool, allow_small: bool, rows: usize, width: usize, nbk: usize, want: fused_trace.Arm) void {
    const got = fused_trace.idxArm(true, wide, allow_small, rows, width, 8, nbk, 2048);
    const ok = got == want;
    if (!ok) fails += 1;
    std.debug.print("{s}: idxArm(wide={any}, rows={d}, nbk={d}) = {s} (want {s}) {s}\n", .{ name, wide, rows, nbk, @tagName(got), @tagName(want), if (ok) "ok" else "FAIL" });
}

pub fn main() !void {
    std.debug.print("h0279 gate: the worktree's idx_pick_wide.wideOk / fused_trace.idxArm at the brief's matrix\n", .{});
    // the wide window (the served widths: a short last block, width = 8 * nbk - 3, and whole blocks)
    for ([_]usize{ 1, 7 }) |rows| {
        arm("16,385 blocks", true, true, rows, 8 * 16385 - 3, 16385, .idx_wide);
        arm("32,768 blocks", true, true, rows, 8 * 32768, 32768, .idx_wide);
        arm("65,536 blocks", true, true, rows, 8 * 65536, 65536, .idx_wide);
        // 65,537 refuses: the unfused fallback (block_max + topk_indices + pool_pick) stays
        arm("65,537 blocks", true, true, rows, 8 * 65537, 65537, .idx_unfused);
    }
    // the refusal's neighbours and the off path
    arm("switch off", false, true, 7, 8 * 32768, 32768, .idx_unfused);
    arm("prompt arm", true, false, 7, 8 * 32768, 32768, .idx_unfused);
    arm("rows 8", true, true, 8, 8 * 32768, 32768, .idx_unfused);
    // today's regimes unchanged (the off path is byte- and launch-identical)
    arm("staging bound (small)", true, true, 7, 8 * 16384, 16384, .idx_small);
    arm("small pool", true, true, 7, 8 * 6144, 6144, .idx_small);
    arm("many rows (fused)", true, true, 32, 8 * 16384, 16384, .idx_fused);
    arm("prompt pooled", true, false, 1, 65533, 8192, .idx_fused);
    arm("everything off", false, true, 7, 65533, 8192, .idx_unfused);
    // the launcher's own bound: wideOk agrees with the arm table at the 65,536/65,537 edge and the k cap
