        fails += 1;
        std.debug.print("wideOk(65,537) must refuse: FAIL\n", .{});
    }
    if (idx_pick_wide.wideOk(true, true, 7, 8 * 16385, 8, 16385, idx_fused.max_k + 1)) {
        fails += 1;
        std.debug.print("wideOk(k=2049) must refuse: FAIL\n", .{});
    }
